{
  "name": "Metal Chemistry Exam Generator",
  "description": "An application to generate high-quality Chemistry exams for the 'General Metals' chapter, adhering to specific formatting rules for MCQs, True/False, and Short Answer questions with English nomenclature.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface MCQQuestion {
  question: string;
  options: string[]; // ['A. ...', 'B. ...', 'C. ...', 'D. ...']
  correctIndex: number;
}

export interface Statement {
  text: string;
  isTrue: boolean;
}

export interface TFScenario {
  context: string;
  statements: Statement[];
}

export interface ShortAnswerQuestion {
  question: string;
  answer: string | number;
}

export interface ExamData {
  title: string;
  part1: MCQQuestion[];
  part2: TFScenario[];
  part3: ShortAnswerQuestion[];
}

export enum AppStatus {
  IDLE = 'IDLE',
  GENERATING = 'GENERATING',
  COMPLETED = 'COMPLETED',
  ERROR = 'ERROR'
}

import { GoogleGenAI, Type } from "@google/genai";
import { ExamData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const generateExam = async (): Promise<ExamData> => {
  const modelName = 'gemini-3-pro-preview';

  const systemInstruction = `
    Bạn là một chuyên gia soạn đề thi Hóa học THPT cấp cao.
    Nhiệm vụ: Tạo đề kiểm tra chương "Đại cương kim loại" (General Chemistry of Metals) - Hóa học 12.

    CẤU TRÚC ĐỀ (3 phần):
    1. Phần 1: 18 câu trắc nghiệm MCQ (A, B, C, D).
    2. Phần 2: 4 bối cảnh (scenarios), mỗi bối cảnh có 4 lệnh hỏi Đúng/Sai (a, b, c, d). Bối cảnh phải gắn với thực tế và dài > 50 từ.
    3. Phần 3: 6 câu hỏi trả lời ngắn, đáp án là con số.

    QUY TẮC NỘI DUNG:
    - Chủ đề: Cấu tạo và tính chất vật lí kim loại, tính chất hóa học, dãy điện hóa, điều chế, hợp kim, ăn mòn.
    - Mức độ: 40% Biết, 30% Hiểu, 30% Vận dụng.
    - NGÔN NGỮ: Câu hỏi và bối cảnh viết bằng TIẾNG VIỆT.
    - DANH PHÁP: Tên các chất hóa học và kim loại PHẢI viết bằng TIẾNG ANH (Ví dụ: Iron(III) oxide, Sodium, Sulfuric acid, Zinc).
    - CÔNG THỨC HÓA HỌC: Viết theo định dạng text với chỉ số dưới/trên được biểu diễn rõ ràng (ví dụ: H2SO4, Fe2+, Cu(NO3)2). 
    - TRÌNH BÀY MCQ: Mỗi phương án bắt đầu bằng "A. ", "B. ", "C. ", "D. ".

    YÊU CẦU JSON:
    Phải trả về dữ liệu đúng cấu trúc JSON quy định.
  `;

  const response = await ai.models.generateContent({
    model: modelName,
    contents: "Hãy soạn một đề kiểm tra chương Đại cương kim loại theo yêu cầu.",
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          part1: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                question: { type: Type.STRING },
                options: { type: Type.ARRAY, items: { type: Type.STRING } },
                correctIndex: { type: Type.INTEGER }
              },
              required: ["question", "options", "correctIndex"]
            }
          },
          part2: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                context: { type: Type.STRING },
                statements: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      text: { type: Type.STRING },
                      isTrue: { type: Type.BOOLEAN }
                    },
                    required: ["text", "isTrue"]
                  }
                }
              },
              required: ["context", "statements"]
            }
          },
          part3: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                question: { type: Type.STRING },
                answer: { type: Type.STRING }
              },
              required: ["question", "answer"]
            }
          }
        },
        required: ["title", "part1", "part2", "part3"]
      }
    }
  });

  const text = response.text;
  if (!text) throw new Error("No response from Gemini");
  return JSON.parse(text) as ExamData;
};

import { Document, Packer, Paragraph, TextRun, AlignmentType, HeadingLevel, Table, TableRow, TableCell, WidthType, BorderStyle } from "docx";
import { saveAs } from "file-saver";
import { ExamData } from "../types";

/**
 * Utility to parse text and handle chemical formulas (subscripts/superscripts)
 * Simplified logic: looks for numbers in common chemical contexts
 */
const parseChemicalText = (text: string): TextRun[] => {
  // A very basic regex-based parser for common chemical patterns
  // It handles simple subscripts like H2SO4 and charges like Fe2+
  // For a production app, a more robust LaTeX or chemical parser would be used
  const parts: TextRun[] = [];

  // Basic logic: split by characters and check if digits should be sub
  // Also handle common superscripts like 2+, 3+, +, -
  let i = 0;
  while (i < text.length) {
    const char = text[i];

    // Check for charges (superscript)
    if ((char === '+' || char === '-') && i > 0 && /\d/.test(text[i-1])) {
       // Charge usually goes with the preceding digit
       // In this simple version, we just append
       parts.push(new TextRun({ text: char, superScript: true }));
       i++;
       continue;
    }

    // Check for digits that are likely subscripts (after a letter)
    if (/\d/.test(char) && i > 0 && /[a-zA-Z]|\)/.test(text[i-1])) {
      parts.push(new TextRun({ text: char, subScript: true }));
    } else if (char === '^' && text[i+1] === '{') {
        // Handle ^{charge} format if the AI uses it
        let end = text.indexOf('}', i);
        if (end !== -1) {
            parts.push(new TextRun({ text: text.substring(i+2, end), superScript: true }));
            i = end;
        } else {
            parts.push(new TextRun({ text: char }));
        }
    } else {
      parts.push(new TextRun({ text: char }));
    }
    i++;
  }
  return parts;
};

// Simplified parser that just returns a single TextRun if it's too complex, 
// but for this task we'll mostly rely on standard TextRun with basic formatting
const createFormattedParagraph = (text: string, options: any = {}) => {
    return new Paragraph({
        children: [new TextRun({ text, ...options })],
        spacing: { after: 120 },
    });
};

export const downloadExamDoc = async (data: ExamData, isAnswerKey: boolean) => {
  const children: any[] = [];

  // Title
  children.push(
    new Paragraph({
      text: data.title.toUpperCase(),
      heading: HeadingLevel.HEADING_1,
      alignment: AlignmentType.CENTER,
      spacing: { after: 400 },
    })
  );

  // Part 1
  children.push(new Paragraph({ text: "PHẦN I. Câu trắc nghiệm nhiều phương án lựa chọn.", bold: true, spacing: { before: 200, after: 100 } }));
  children.push(new Paragraph({ text: "Thí sinh trả lời từ câu 1 đến câu 18. Mỗi câu hỏi thí sinh chỉ chọn một phương án.", italic: true, spacing: { after: 200 } }));

  data.part1.forEach((q, idx) => {
    children.push(new Paragraph({ children: [new TextRun({ text: `Câu ${idx + 1}. `, bold: true }), new TextRun(q.question)], spacing: { before: 100 } }));

    q.options.forEach((opt, oIdx) => {
      const isCorrect = oIdx === q.correctIndex && isAnswerKey;
      children.push(
        new Paragraph({
          children: [
            new TextRun({
              text: opt,
              bold: isCorrect,
              italics: isCorrect,
              underline: isCorrect ? {} : undefined,
            }),
          ],
          indent: { left: 720 },
        })
      );
    });
  });

  // Part 2
  children.push(new Paragraph({ text: "PHẦN II. Câu trắc nghiệm đúng sai.", bold: true, spacing: { before: 400, after: 100 } }));
  children.push(new Paragraph({ text: "Thí sinh trả lời từ câu 1 đến câu 4. Trong mỗi ý a), b), c), d) ở mỗi câu, thí sinh chọn đúng hoặc sai.", italic: true, spacing: { after: 200 } }));

  data.part2.forEach((sc, idx) => {
    children.push(new Paragraph({ children: [new TextRun({ text: `Câu ${idx + 1}. `, bold: true }), new TextRun(sc.context)], spacing: { before: 100 } }));

    sc.statements.forEach((st, sIdx) => {
      const letter = ["a", "b", "c", "d"][sIdx];
      const isTrue = st.isTrue && isAnswerKey;
      children.push(
        new Paragraph({
          children: [
            new TextRun({ text: `${letter}) `, bold: true }),
            new TextRun({
              text: st.text,
              bold: isTrue,
              italics: isTrue,
              underline: isTrue ? {} : undefined,
            }),
          ],
          indent: { left: 720 },
        })
      );
    });
  });

  // Part 3
  children.push(new Paragraph({ text: "PHẦN III. Câu trắc nghiệm trả lời ngắn.", bold: true, spacing: { before: 400, after: 100 } }));
  children.push(new Paragraph({ text: "Thí sinh trả lời từ câu 1 đến câu 6.", italic: true, spacing: { after: 200 } }));

  data.part3.forEach((q, idx) => {
    children.push(new Paragraph({ children: [new TextRun({ text: `Câu ${idx + 1}. `, bold: true }), new TextRun(q.question)], spacing: { before: 100 } }));
    if (isAnswerKey) {
      children.push(new Paragraph({ children: [new TextRun({ text: `A. ${q.answer}`, bold: true, underline: {} })], indent: { left: 720 } }));
    } else {
      children.push(new Paragraph({ text: "A. ...........................................................", indent: { left: 720 } }));
    }
  });

  const doc = new Document({
    sections: [{
      properties: {},
      children: children,
    }],
  });

  const blob = await Packer.toBlob(doc);
  saveAs(blob, `${isAnswerKey ? 'DapAn' : 'DeThi'}_${data.title.replace(/\s+/g, '_')}.docx`);
};

import React from 'react';
import { ExamData } from '../types';

interface ExamRendererProps {
  data: ExamData;
  showAnswers?: boolean;
}

const ExamRenderer: React.FC<ExamRendererProps> = ({ data, showAnswers = false }) => {
  // Simple regex to make chemical numbers look slightly better in preview
  const formatFormula = (text: string) => {
    // This is a crude preview formatter, docx generator has its own logic
    return text.split(/(\d+)/).map((part, i) => 
      /^\d+$/.test(part) ? <sub key={i} className="text-[0.7em]">{part}</sub> : part
    );
  };

  return (
    <div id="exam-preview" className="bg-white p-8 md:p-12 shadow-xl rounded-lg border border-slate-200 max-w-4xl mx-auto text-slate-800 leading-relaxed overflow-hidden">
      <h1 className="text-2xl font-bold text-center mb-8 uppercase text-slate-900 border-b pb-4">
        {data.title}
      </h1>

      {/* Part 1 */}
      <section className="mb-10">
        <h2 className="font-bold text-lg mb-2">PHẦN I. Câu trắc nghiệm nhiều phương án lựa chọn.</h2>
        <p className="italic text-sm mb-4 text-slate-600">Thí sinh trả lời từ câu 1 đến câu 18. Mỗi câu hỏi thí sinh chỉ chọn một phương án.</p>

        <div className="space-y-6">
          {data.part1.map((q, idx) => (
            <div key={idx} className="pl-2 border-l-2 border-slate-100">
              <p className="font-medium">
                <span className="font-bold">Câu {idx + 1}.</span> {formatFormula(q.question)}
              </p>
              <div className="mt-2 grid grid-cols-1 gap-1">
                {q.options.map((opt, oIdx) => {
                  const isCorrect = showAnswers && oIdx === q.correctIndex;
                  return (
                    <p key={oIdx} className={`pl-6 ${isCorrect ? 'italic font-bold underline text-blue-700' : ''}`}>
                      {opt}
                    </p>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* Part 2 */}
      <section className="mb-10">
        <h2 className="font-bold text-lg mb-2">PHẦN II. Câu trắc nghiệm đúng sai.</h2>
        <p className="italic text-sm mb-4 text-slate-600">Thí sinh trả lời từ câu 1 đến câu 4. Trong mỗi ý a), b), c), d) ở mỗi câu, thí sinh chọn đúng hoặc sai.</p>

        <div className="space-y-8">
          {data.part2.map((sc, idx) => (
            <div key={idx} className="pl-2 border-l-2 border-slate-100">
              <div className="font-medium mb-3">
                <span className="font-bold">Câu {idx + 1}.</span> {formatFormula(sc.context)}
              </div>
              <div className="space-y-2">
                {sc.statements.map((st, sIdx) => {
                  const letter = ["a", "b", "c", "d"][sIdx];
                  const isCorrect = showAnswers && st.isTrue;
                  return (
                    <div key={sIdx} className="flex gap-2 pl-6">
                      <span className="font-bold whitespace-nowrap">{letter})</span>
                      <p className={`${isCorrect ? 'italic font-bold underline text-blue-700' : ''}`}>
                        {formatFormula(st.text)}
                      </p>
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* Part 3 */}
      <section>
        <h2 className="font-bold text-lg mb-2">PHẦN III. Câu trắc nghiệm trả lời ngắn.</h2>
        <p className="italic text-sm mb-4 text-slate-600">Thí sinh trả lời từ câu 1 đến câu 6.</p>

        <div className="space-y-6">
          {data.part3.map((q, idx) => (
            <div key={idx} className="pl-2 border-l-2 border-slate-100">
              <p className="font-medium">
                <span className="font-bold">Câu {idx + 1}.</span> {formatFormula(q.question)}
              </p>
              <div className="mt-2 pl-6">
                {showAnswers ? (
                  <p className="font-bold text-blue-700 underline">A. {q.answer}</p>
                ) : (
                  <div className="flex items-center gap-2">
                    <span className="font-medium">A.</span>
                    <div className="w-48 border-b-2 border-dotted border-slate-400 h-6"></div>
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
};

export default ExamRenderer;

import React, { useState, useCallback } from 'react';
import { generateExam } from './services/geminiService';
import { downloadExamDoc } from './services/docxService';
import { ExamData, AppStatus } from './types';
import ExamRenderer from './components/ExamRenderer';
import { FileText, Download, Copy, RefreshCw, Beaker, Loader2, CheckCircle, AlertCircle } from 'lucide-react';

const App: React.FC = () => {
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [exam, setExam] = useState<ExamData | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);

  const handleGenerate = async () => {
    setStatus(AppStatus.GENERATING);
    setError(null);
    try {
      const data = await generateExam();
      setExam(data);
      setStatus(AppStatus.COMPLETED);
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Có lỗi xảy ra khi tạo đề thi. Vui lòng thử lại.');
      setStatus(AppStatus.ERROR);
    }
  };

  const handleCopy = () => {
    const el = document.getElementById('exam-preview');
    if (el) {
      const range = document.createRange();
      range.selectNode(el);
      window.getSelection()?.removeAllRanges();
      window.getSelection()?.addRange(range);
      document.execCommand('copy');
      window.getSelection()?.removeAllRanges();
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <div className="min-h-screen pb-20">
      {/* Header */}
      <header className="bg-indigo-700 text-white shadow-lg sticky top-0 z-50">
        <div className="max-w-6xl mx-auto px-4 py-4 flex flex-col md:flex-row items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-white/20 rounded-lg">
              <Beaker className="w-6 h-6" />
            </div>
            <div>
              <h1 className="font-bold text-xl leading-tight">ExamGen Chemistry</h1>
              <p className="text-xs text-indigo-100">Đại cương Kim loại (General Metals)</p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            {status === AppStatus.COMPLETED && (
              <>
                <button 
                  onClick={() => downloadExamDoc(exam!, false)}
                  className="flex items-center gap-2 bg-white/10 hover:bg-white/20 text-white px-4 py-2 rounded-full text-sm font-medium transition-colors"
                >
                  <Download className="w-4 h-4" />
                  <span>Tải Đề (.doc)</span>
                </button>
                <button 
                  onClick={() => downloadExamDoc(exam!, true)}
                  className="flex items-center gap-2 bg-white/10 hover:bg-white/20 text-white px-4 py-2 rounded-full text-sm font-medium transition-colors"
                >
                  <CheckCircle className="w-4 h-4" />
                  <span>Tải Đáp Án (.doc)</span>
                </button>
                <button 
                  onClick={handleCopy}
                  className="flex items-center gap-2 bg-white/10 hover:bg-white/20 text-white px-4 py-2 rounded-full text-sm font-medium transition-colors"
                >
                  <Copy className="w-4 h-4" />
                  <span>{copied ? 'Đã Copy!' : 'Copy Đề'}</span>
                </button>
              </>
            )}

            <button 
              onClick={handleGenerate}
              disabled={status === AppStatus.GENERATING}
              className={`flex items-center gap-2 px-6 py-2 rounded-full font-bold shadow-md transition-all ${
                status === AppStatus.GENERATING 
                  ? 'bg-slate-200 text-slate-500 cursor-not-allowed'
                  : 'bg-yellow-400 hover:bg-yellow-300 text-slate-900 active:scale-95'
              }`}
            >
              {status === AppStatus.GENERATING ? <Loader2 className="w-4 h-4 animate-spin" /> : <RefreshCw className="w-4 h-4" />}
              <span>{exam ? 'TẠO ĐỀ MỚI' : 'TẠO ĐỀ MỚI'}</span>
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-5xl mx-auto px-4 py-8">
        {status === AppStatus.IDLE && (
          <div className="flex flex-col items-center justify-center min-h-[60vh] text-center">
            <div className="w-24 h-24 bg-indigo-100 text-indigo-600 rounded-full flex items-center justify-center mb-6">
              <FileText className="w-12 h-12" />
            </div>
            <h2 className="text-3xl font-bold text-slate-800 mb-4">Chào mừng đến với Hệ thống Tạo Đề thi Hóa học</h2>
            <p className="text-slate-600 max-w-lg mb-8">
              Ứng dụng hỗ trợ giáo viên tạo đề kiểm tra chương <b>Đại cương Kim loại</b> tự động với cấu trúc chuẩn 3 phần, hỗ trợ tải về file Word và đáp án chi tiết.
            </p>
            <button 
              onClick={handleGenerate}
              className="bg-indigo-600 hover:bg-indigo-700 text-white px-10 py-4 rounded-full text-lg font-bold shadow-xl transition-all active:scale-95 flex items-center gap-3"
            >
              <RefreshCw className="w-5 h-5" />
              TẠO ĐỀ MỚI
            </button>
          </div>
        )}

        {status === AppStatus.GENERATING && (
          <div className="flex flex-col items-center justify-center min-h-[60vh] text-center">
            <div className="relative">
              <Loader2 className="w-16 h-16 text-indigo-600 animate-spin" />
              <Beaker className="w-6 h-6 text-indigo-400 absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2" />
            </div>
            <h2 className="text-2xl font-bold text-slate-800 mt-6 mb-2">Đang soạn đề thi...</h2>
            <p className="text-slate-500">Gemini đang biên soạn 18 câu MCQ, 4 bối cảnh thực tế và các câu hỏi tính toán.</p>
            <div className="mt-8 w-64 h-2 bg-slate-200 rounded-full overflow-hidden">
               <div className="h-full bg-indigo-600 animate-progress"></div>
            </div>
            <style>{`
              @keyframes progress {
                0% { width: 0%; }
                50% { width: 70%; }
                100% { width: 95%; }
              }
              .animate-progress {
                animation: progress 15s ease-in-out infinite;
              }
            `}</style>
          </div>
        )}

        {status === AppStatus.ERROR && (
          <div className="flex flex-col items-center justify-center min-h-[60vh] text-center">
            <div className="w-16 h-16 bg-red-100 text-red-600 rounded-full flex items-center justify-center mb-4">
              <AlertCircle className="w-10 h-10" />
            </div>
            <h2 className="text-2xl font-bold text-slate-800 mb-2">Đã xảy ra lỗi</h2>
            <p className="text-red-500 mb-8">{error}</p>
            <button 
              onClick={handleGenerate}
              className="bg-indigo-600 hover:bg-indigo-700 text-white px-8 py-3 rounded-full font-bold"
            >
              Thử Lại
            </button>
          </div>
        )}

        {status === AppStatus.COMPLETED && exam && (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <h3 className="text-lg font-bold text-slate-700 flex items-center gap-2">
                  <FileText className="w-5 h-5 text-indigo-600" />
                  Bản xem trước ĐỀ THI
                </h3>
              </div>
              <ExamRenderer data={exam} showAnswers={false} />
            </div>

            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <h3 className="text-lg font-bold text-slate-700 flex items-center gap-2">
                  <CheckCircle className="w-5 h-5 text-green-600" />
                  Bản xem trước ĐÁP ÁN
                </h3>
              </div>
              <ExamRenderer data={exam} showAnswers={true} />
            </div>
          </div>
        )}
      </main>

      {/* Floating Action Button for Mobile */}
      {status === AppStatus.COMPLETED && (
