    q.options.forEach((opt, oIdx) => {
      const isCorrect = oIdx === q.correctIndex && isAnswerKey;
      if (!isAnswerKey || isCorrect) {
          children.push(
            new Paragraph({
              children: parseChemicalText(opt, {
                italics: isCorrect,
                underline: isCorrect ? {} : undefined,
                bold: isCorrect,
              }),
              indent: { left: 720 },
              spacing: { before: 0, after: 0 }
            })
          );
      }
    });
  });

  // Part 2
  children.push(new Paragraph({ text: "PHẦN II. Câu trắc nghiệm đúng sai.", bold: true, spacing: sectionSpacing }));
  if (!isAnswerKey) {
    children.push(new Paragraph({ text: "Thí sinh trả lời từ câu 1 đến câu 4. Trong mỗi ý a), b), c), d) ở mỗi câu, thí sinh chọn đúng hoặc sai.", italic: true, spacing: { after: 200 } }));
