export const downloadExamDoc = async (data: ExamData, isAnswerKey: boolean) => {
  const children: any[] = [];

  // File đáp án không có dãn dòng để tiết kiệm giấy
  const pSpacing = isAnswerKey ? { before: 0, after: 0 } : { before: 100, after: 100 };
  const sectionSpacing = isAnswerKey ? { before: 120, after: 0 } : { before: 400, after: 100 };

  // Title
  children.push(
    new Paragraph({
      text: data.title.toUpperCase() + (isAnswerKey ? " - ĐÁP ÁN" : ""),
      heading: HeadingLevel.HEADING_1,
      alignment: AlignmentType.CENTER,
      spacing: isAnswerKey ? { after: 150 } : { after: 400 },
    })
  );

  // PHẦN I
  children.push(new Paragraph({ text: "PHẦN I. Câu trắc nghiệm nhiều phương án lựa chọn.", bold: true, spacing: sectionSpacing }));
  if (!isAnswerKey) {
    children.push(new Paragraph({ text: "Thí sinh trả lời từ câu 1 đến câu 18. Mỗi câu hỏi thí sinh chỉ chọn một phương án.", italic: true, spacing: { after: 150 } }));
  }

  data.part1.forEach((q, idx) => {
    children.push(new Paragraph({ 
      children: [new TextRun({ text: `Câu ${idx + 1}. `, bold: true }), ...parseChemicalText(q.question)], 
      spacing: isAnswerKey ? { before: 40 } : { before: 100, after: 40 } 
    }));

    q.options.forEach((opt, oIdx) => {
      const isCorrect = oIdx === q.correctIndex && isAnswerKey;
      children.push(
        new Paragraph({
          children: parseChemicalText(opt, {
            italics: isCorrect,
            underline: isCorrect ? {} : undefined,
            bold: isCorrect,
          }),
          indent: { left: 450 },
          spacing: { before: 0, after: 0 }
        })
      );
    });
  });

  // PHẦN II
  children.push(new Paragraph({ text: "PHẦN II. Câu trắc nghiệm đúng sai.", bold: true, spacing: sectionSpacing }));
  if (!isAnswerKey) {
    children.push(new Paragraph({ text: "Thí sinh trả lời từ câu 1 đến câu 4. Trong mỗi ý a), b), c), d) ở mỗi câu, thí sinh chọn đúng hoặc sai.", italic: true, spacing: { after: 150 } }));
  }

  data.part2.forEach((sc, idx) => {
    children.push(new Paragraph({ 
      children: [new TextRun({ text: `Câu ${idx + 1}. `, bold: true }), ...parseChemicalText(sc.context)], 
      spacing: isAnswerKey ? { before: 80 } : { before: 150, after: 80 } 
    }));

    sc.statements.forEach((st, sIdx) => {
      const letter = ["a", "b", "c", "d"][sIdx];
      // Trong file đáp án: in nghiêng và gạch chân nếu đó là đáp án đúng cho lệnh hỏi đó
      // Đối với câu Đúng/Sai, "đáp án đúng" có thể hiểu là trạng thái Đúng.
      // Tuy nhiên giáo viên thường muốn biết ý đó là Đúng hay Sai. 
      // Ta sẽ dùng format: In nghiêng + Gạch chân cho ý ĐÚNG. Ý SAI để bình thường (hoặc ngược lại).
      // Để rõ ràng hơn theo yêu cầu "không ghi ĐÚNG/SAI", ta quy ước: 
      // Ý nào ĐÚNG thì in nghiêng + gạch chân. Ý nào SAI thì để nguyên.
      const isTrueMark = st.isTrue && isAnswerKey;

      children.push(
        new Paragraph({
          children: [
            new TextRun({ text: `${letter}) `, bold: true }),
            ...parseChemicalText(st.text, {
              italics: isTrueMark,
              underline: isTrueMark ? {} : undefined,
              bold: isTrueMark
            })
          ],
          indent: { left: 450 },
          spacing: { before: 0, after: 0 }
        })
      );
    });
  });

  // PHẦN III
  children.push(new Paragraph({ text: "PHẦN III. Câu trắc nghiệm trả lời ngắn.", bold: true, spacing: sectionSpacing }));
  if (!isAnswerKey) {
    children.push(new Paragraph({ text: "Thí sinh trả lời từ câu 1 đến câu 6.", italic: true, spacing: { after: 150 } }));
  }

  data.part3.forEach((q, idx) => {
    children.push(new Paragraph({ 
      children: [new TextRun({ text: `Câu ${idx + 1}. `, bold: true }), ...parseChemicalText(q.question)], 
      spacing: isAnswerKey ? { before: 80 } : { before: 150, after: 80 } 
    }));

    if (isAnswerKey) {
      children.push(new Paragraph({ 
        children: [
          new TextRun({ text: "Đáp số: ", bold: true }),
          new TextRun({ text: `${q.answer}`, bold: true, italics: true, underline: {}, color: "0000FF" })
        ], 
        indent: { left: 450 },
        spacing: { before: 0, after: 0 }
      }));
    } else {
      children.push(new Paragraph({ text: "A. ...........................................................", indent: { left: 450 }, spacing: { before: 0, after: 0 } }));
    }
  });

  const doc = new Document({
    sections: [{
      properties: {
          page: { margin: { top: 720, bottom: 720, left: 720, right: 720 } }
      },
      children: children,
    }],
  });

  const blob = await Packer.toBlob(doc);
  saveAs(blob, `${isAnswerKey ? 'DapAn' : 'DeThi'}_${data.title.replace(/\s+/g, '_')}.docx`);
};

