/**
 * Utility to parse text and handle chemical formulas (subscripts/superscripts)
 * Recognizes ions like Fe2+, OH-, SO42- and molecules like H2SO4.
 */
const parseChemicalText = (text: string, baseOptions: any = {}): TextRun[] => {
  const parts: TextRun[] = [];

  // Regex explanation:
  // 1. ((?<=[a-zA-Z\d\)])\d*[\+\-]): Superscript charges (e.g., 2+, +, 3-) preceded by letter/digit/bracket
  // 2. ((?<=[a-zA-Z\)])\d+): Subscript numbers (e.g., 2 in H2) preceded by letter
  const regex = /((?<= [a-zA-Z\d\)])\d*[\+\-]|(?<=[a-zA-Z\)])\d+)/g;

  // Note: Modern browsers support lookbehind. If targeting very old environments, 
  // we would need a character-by-character parser.

  const tokens = text.split(/((?<=[a-zA-Z\d\)])\d*[\+\-]|(?<=[a-zA-Z\)])\d+)/g);

  tokens.forEach((token) => {
    if (!token) return;

    // Check if it's a charge (superscript)
    if (/^\d*[\+\-]$/.test(token)) {
      parts.push(new TextRun({ ...baseOptions, text: token, superScript: true }));
    } 
    // Check if it's a subscript (just digits preceded by letter in original context)
    else if (/^\d+$/.test(token)) {
      parts.push(new TextRun({ ...baseOptions, text: token, subScript: true }));
    } 
    // Normal text
    else {
      parts.push(new TextRun({ ...baseOptions, text: token }));
    }
  });

  return parts.length > 0 ? parts : [new TextRun({ ...baseOptions, text: text })];
};

