}

const ExamRenderer: React.FC<ExamRendererProps> = ({ data, showAnswers = false }) => {
  const formatFormula = (text: string) => {
    // Regex matches:
    // 1. Charges (superscript): \d*[+-] preceded by letter/digit/bracket
    // 2. Formula subscripts: \d+ preceded by letter
    const regex = /((?<=[a-zA-Z\d\)])\d*[\+\-]|(?<=[a-zA-Z])\d+)/g;
    const parts = text.split(regex);

    return parts.map((part, i) => {
      if (!part) return null;

      // If it's a charge (e.g., 2+, 3-, +)
      if (/^\d*[\+\-]$/.test(part)) {
        return <sup key={i} className="text-[0.75em] leading-none">{part}</sup>;
      }

      // If it's a numeric subscript (e.g., 2 in H2)
      // Note: we only match digits that are preceded by a letter in the full text
      if (/^\d+$/.test(part)) {
        return <sub key={i} className="text-[0.75em] leading-none">{part}</sub>;
      }

      return part;
    });
  };

  return (
    <div id="exam-preview" className={`bg-white p-6 md:p-10 shadow-xl rounded-lg border border-slate-200 max-w-4xl mx-auto text-slate-800 leading-tight overflow-hidden ${showAnswers ? 'bg-blue-50/30' : ''}`}>
