              </p>
              <div className="mt-1 grid grid-cols-1 gap-0.5">
                {q.options.map((opt, oIdx) => {
                  const isCorrect = showAnswers && oIdx === q.correctIndex;
                  return (
                    <p key={oIdx} className={`pl-5 ${isCorrect ? 'italic underline text-blue-700 bg-yellow-50' : ''}`}>
                      {formatFormula(opt)}
