/**
 * Phân tích văn bản để xử lý công thức hóa học (chỉ số trên/dưới)
 * Nhận diện ion (Fe2+, OH-, SO42-) và phân tử (H2SO4, Cu(NO3)2).
 */
const parseChemicalText = (text: string, baseOptions: any = {}): TextRun[] => {
  if (!text) return [];

  const parts: TextRun[] = [];

  // Regex: 
  // 1. (?<=[a-zA-Z\d\)])\d*[\+\-] : Chỉ số trên (điện tích ion), đứng sau chữ, số hoặc đóng ngoặc.
  // 2. (?<=[a-zA-Z\)])\d+ : Chỉ số dưới (số lượng nguyên tử), đứng sau chữ hoặc đóng ngoặc.
  const regex = /((?<=[a-zA-Z\d\)])\d*[\+\-]|(?<=[a-zA-Z\)])\d+)/g;

  // Tách chuỗi dựa trên regex và giữ lại các phần khớp (delimiters)
  const tokens = text.split(regex);

  tokens.forEach((token) => {
    if (!token) return;

    // Kiểm tra nếu là điện tích (chỉ số trên)
    if (/^\d*[\+\-]$/.test(token)) {
      parts.push(new TextRun({ ...baseOptions, text: token, superScript: true }));
    } 
    // Kiểm tra nếu là số lượng nguyên tử (chỉ số dưới)
    else if (/^\d+$/.test(token)) {
      parts.push(new TextRun({ ...baseOptions, text: token, subScript: true }));
    } 
    // Văn bản bình thường
    else {
      parts.push(new TextRun({ ...baseOptions, text: token }));
    }
  });

  return parts.length > 0 ? parts : [new TextRun({ ...baseOptions, text: text })];
};

