import { GoogleGenAI, Type } from "@google/genai";
import { ExamData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const generateExam = async (grade: string, topic: string, details: string): Promise<ExamData> => {
  const modelName = 'gemini-3-pro-preview';

  const systemInstruction = `
    Bạn là một chuyên gia soạn đề thi Hóa học THPT theo chương trình GDPT 2018 và cấu trúc định dạng đề thi mới 2025 của Bộ Giáo dục.
    Nhiệm vụ: Tạo đề kiểm tra và ma trận cho KHỐI ${grade}.
    Chủ đề: "${topic}".
    Yêu cầu cụ thể: "${details || "Bao quát toàn bộ chương"}".

    QUY TẮC PHÂN BỔ TỈ LỆ NHẬN THỨC (BẮT BUỘC):
    - Nhận biết: 40% (Khoảng 11-12 lệnh hỏi/câu hỏi).
    - Thông hiểu: 30% (Khoảng 8-9 lệnh hỏi/câu hỏi).
    - Vận dụng & Vận dụng cao: 30% (Khoảng 8-9 lệnh hỏi/câu hỏi).

    CẤU TRÚC ĐỀ (Tổng 28 câu):
    1. Phần 1: 18 câu trắc nghiệm MCQ (A, B, C, D). Mỗi câu 0.25đ. 
       - Phân bổ: ~10 câu Nhận biết, ~8 câu Thông hiểu.
    2. Phần 2: 4 bối cảnh thí nghiệm/thực tế. Mỗi bối cảnh 4 lệnh Đúng/Sai.
       - Phân bổ: Kết hợp Thông hiểu và Vận dụng. Mỗi bối cảnh nên có ít nhất 1-2 ý Vận dụng.
    3. Phần 3: 6 câu hỏi trả lời ngắn. 
       - YÊU CẦU: PHẢI LÀ CÁC BÀI TOÁN CÓ Ý NGHĨA (định lượng, thực tiễn).
       - Phân bổ: 100% Vận dụng và Vận dụng cao.

    MA TRẬN:
    - Phải trả về mảng "matrix" sao cho tổng số câu/lệnh hỏi ở các cột Nhận biết : Thông hiểu : Vận dụng (bao gồm cả Vận dụng cao) xấp xỉ tỉ lệ 4:3:3.

    QUY TẮC NỘI DUNG:
    - NGÔN NGỮ: Tiếng Việt.
    - DANH PHÁP: Tiếng Anh chuẩn IUPAC.
    - CÔNG THỨC: Viết dạng text (H2SO4, Fe2+...).

    YÊU CẦU JSON: Trả về object chứa title, grade, part1, part2, part3 và matrix.
  `;

  const response = await ai.models.generateContent({
    model: modelName,
    contents: `Soạn đề ôn tập Hóa ${grade} - Chương: ${topic}. 
    Yêu cầu bổ sung: ${details}.
    LƯU Ý NGHIÊM NGẶT: Đảm bảo tỉ lệ ma trận Nhận biết 40%, Thông hiểu 30%, Vận dụng 30%. Phần III phải là các bài toán tính toán định lượng có ý nghĩa thực tế.`,
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          grade: { type: Type.STRING },
          part1: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                question: { type: Type.STRING },
                options: { type: Type.ARRAY, items: { type: Type.STRING } },
                correctIndex: { type: Type.INTEGER }
              },
              required: ["question", "options", "correctIndex"]
            }
          },
          part2: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                context: { type: Type.STRING },
                statements: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      text: { type: Type.STRING },
                      isTrue: { type: Type.BOOLEAN }
                    },
                    required: ["text", "isTrue"]
                  }
                }
              },
              required: ["context", "statements"]
            }
          },
          part3: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                question: { type: Type.STRING },
                answer: { type: Type.STRING }
              },
              required: ["question", "answer"]
            }
          },
          matrix: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                topic: { type: Type.STRING },
                recognition: { type: Type.INTEGER },
                understanding: { type: Type.INTEGER },
                application: { type: Type.INTEGER },
                highApplication: { type: Type.INTEGER }
              },
              required: ["topic", "recognition", "understanding", "application", "highApplication"]
            }
          }
        },
        required: ["title", "grade", "part1", "part2", "part3", "matrix"]
      }
    }
  });

  const text = response.text;
  if (!text) throw new Error("Không nhận được phản hồi từ AI");
  return JSON.parse(text) as ExamData;
};

