import { GoogleGenAI, Type } from "@google/genai";
import { ExamData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const generateExam = async (grade: string, topic: string, details: string): Promise<ExamData> => {
  const modelName = 'gemini-3-pro-preview';

  const systemInstruction = `
    Bạn là một chuyên gia soạn đề thi Hóa học THPT xuất sắc, am hiểu sâu sắc chương trình GDPT 2018.
    Nhiệm vụ: Tạo đề kiểm tra và ma trận cho KHỐI ${grade} - Chương: "${topic}".

    NGUỒN KIẾN THỨC TỔNG HỢP (BẮT BUỘC):
    1. Tổng hợp nội dung từ 3 bộ sách giáo khoa hiện hành: Kết nối tri thức với cuộc sống, Cánh Diều, Chân trời sáng tạo.
    2. Tham khảo chuẩn kiến thức và các dạng bài tập thực tiễn từ các nguồn quốc tế uy tín:
       - Khan Academy, Chemistry LibreTexts, American Chemical Society (ACS).
       - Royal Society of Chemistry (RSC), AP Chemistry (College Board).
       - Chemistry World, ChemCollective (Virtual Labs), Albert.io.

    QUY TẮC PHÂN BỔ TỈ LỆ NHẬN THỨC:
    - Nhận biết: 40% (~11-12 lệnh hỏi).
    - Thông hiểu: 30% (~8-9 lệnh hỏi).
    - Vận dụng & Vận dụng cao: 30% (~8-9 lệnh hỏi).

    CẤU TRÚC ĐỀ (Tổng 28 câu):
    1. Phần 1: 18 câu trắc nghiệm MCQ (A, B, C, D). Mỗi câu 0.25đ. Tập trung Nhận biết (10 câu) & Thông hiểu (8 câu).
    2. Phần 2: 4 bối cảnh thí nghiệm/thực tế. Mỗi bối cảnh 4 lệnh Đúng/Sai. Phải có tính ứng dụng thực tiễn cao, dựa trên các bài lab hoặc tình huống thực tế từ RSC/ACS.
    3. Phần 3: 6 câu hỏi trả lời ngắn. Phải là các BÀI TOÁN ĐỊNH LƯỢNG có ý nghĩa, xử lý số liệu thực nghiệm, tính toán hiệu suất hoặc nồng độ phức tạp tương đương trình độ AP Chemistry/HSG.

    QUY TẮC NỘI DUNG:
    - NGÔN NGỮ: Tiếng Việt.
    - DANH PHÁP: Tiếng Anh chuẩn IUPAC hoàn toàn.
    - CÔNG THỨC: Viết dạng text chuẩn hóa (ví dụ: NH3, [Cu(NH3)4]2+...).

    LƯU Ý RIÊNG: Các câu hỏi phần Vận dụng nên lấy cảm hứng từ các tình huống thực tế trong công nghiệp, y sinh và môi trường được đề cập trong các tạp chí Chemistry World hoặc các thí nghiệm ảo của ChemCollective.
  `;

  const response = await ai.models.generateContent({
    model: modelName,
    contents: `Soạn đề ôn tập Hóa ${grade} - Chương: ${topic}. 
    Yêu cầu bổ sung: ${details}.
    Đảm bảo nội dung là sự giao thoa của 3 bộ sách giáo khoa (Kết nối, Cánh Diều, Chân trời) và nâng tầm bằng các dạng bài thực tiễn từ ACS, RSC và AP Chemistry.`,
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          grade: { type: Type.STRING },
          part1: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                question: { type: Type.STRING },
                options: { type: Type.ARRAY, items: { type: Type.STRING } },
                correctIndex: { type: Type.INTEGER }
              },
              required: ["question", "options", "correctIndex"]
            }
          },
          part2: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                context: { type: Type.STRING },
                statements: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      text: { type: Type.STRING },
                      isTrue: { type: Type.BOOLEAN }
                    },
                    required: ["text", "isTrue"]
                  }
                }
              },
              required: ["context", "statements"]
            }
          },
          part3: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                question: { type: Type.STRING },
                answer: { type: Type.STRING }
              },
              required: ["question", "answer"]
            }
          },
          matrix: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                topic: { type: Type.STRING },
                recognition: { type: Type.INTEGER },
                understanding: { type: Type.INTEGER },
                application: { type: Type.INTEGER },
                highApplication: { type: Type.INTEGER }
              },
              required: ["topic", "recognition", "understanding", "application", "highApplication"]
            }
          }
        },
        required: ["title", "grade", "part1", "part2", "part3", "matrix"]
      }
    }
  });

  const text = response.text;
  if (!text) throw new Error("Không nhận được phản hồi từ AI");
  return JSON.parse(text) as ExamData;
};

