import { Document, Packer, Paragraph, TextRun, AlignmentType, HeadingLevel } from "docx";
import saveAs from "file-saver";
import { ExamData } from "../types";

const parseChemicalText = (text: string, baseOptions: any = {}): TextRun[] => {
  if (!text) return [];
  const parts: TextRun[] = [];
  const regex = /((?<=[a-zA-Z\d\)])\d*[\+\-]|(?<=[a-zA-Z\)])\d+)/g;
  const tokens = text.split(regex);

  tokens.forEach((token) => {
    if (!token) return;
    if (/^\d*[\+\-]$/.test(token)) {
      parts.push(new TextRun({ ...baseOptions, text: token, superScript: true }));
    } else if (/^\d+$/.test(token)) {
      parts.push(new TextRun({ ...baseOptions, text: token, subScript: true }));
    } else {
      parts.push(new TextRun({ ...baseOptions, text: token }));
    }
  });
  return parts.length > 0 ? parts : [new TextRun({ ...baseOptions, text: text })];
};

export const downloadExamDoc = async (data: ExamData, isAnswerKey: boolean) => {
  const children: any[] = [];
  const sectionSpacing = isAnswerKey ? { before: 120, after: 0 } : { before: 400, after: 100 };

  children.push(
    new Paragraph({
      text: data.title.toUpperCase() + (isAnswerKey ? " - ĐÁP ÁN" : ""),
      heading: HeadingLevel.HEADING_1,
      alignment: AlignmentType.CENTER,
      spacing: isAnswerKey ? { after: 150 } : { after: 400 },
    })
  );

  // PHẦN I
  children.push(new Paragraph({ text: "PHẦN I. Câu trắc nghiệm nhiều phương án lựa chọn.", bold: true, spacing: sectionSpacing }));
  if (!isAnswerKey) {
    children.push(new Paragraph({ text: "Thí sinh trả lời từ câu 1 đến câu 18. Mỗi câu hỏi thí sinh chỉ chọn một phương án.", italic: true, spacing: { after: 150 } }));
  }

  const labels = ["A", "B", "C", "D"];

  data.part1.forEach((q, idx) => {
    children.push(new Paragraph({ 
      children: [new TextRun({ text: `Câu ${idx + 1}. `, bold: true }), ...parseChemicalText(q.question)], 
      spacing: isAnswerKey ? { before: 40 } : { before: 100, after: 40 } 
    }));

    q.options.forEach((opt, oIdx) => {
      const isCorrect = oIdx === q.correctIndex && isAnswerKey;
      const labelStr = `${labels[oIdx]}. `;
      const cleanOpt = opt.replace(/^[A-D]\.\s*/, '');

      children.push(
        new Paragraph({
          children: [
            new TextRun({
              text: labelStr,
              italics: isCorrect,
              underline: isCorrect ? {} : undefined,
              bold: isCorrect,
            }),
            ...parseChemicalText(cleanOpt, {
              italics: isCorrect,
              underline: isCorrect ? {} : undefined,
              bold: false,
            })
          ],
          indent: { left: 450 },
          spacing: { before: 0, after: 0 }
        })
      );
    });
  });

  // PHẦN II
  children.push(new Paragraph({ text: "PHẦN II. Câu trắc nghiệm đúng sai.", bold: true, spacing: sectionSpacing }));
  if (!isAnswerKey) {
    children.push(new Paragraph({ text: "Thí sinh trả lời từ câu 1 đến câu 4. Trong mỗi ý a), b), c), d) ở mỗi câu, thí sinh chọn đúng hoặc sai.", italic: true, spacing: { after: 150 } }));
  }

  data.part2.forEach((sc, idx) => {
    children.push(new Paragraph({ 
      children: [new TextRun({ text: `Câu ${idx + 1}. `, bold: true }), ...parseChemicalText(sc.context)], 
      spacing: isAnswerKey ? { before: 80 } : { before: 150, after: 80 } 
    }));

    sc.statements.forEach((st, sIdx) => {
      const letter = ["a", "b", "c", "d"][sIdx];
      const isTrueMark = st.isTrue && isAnswerKey;

      children.push(
        new Paragraph({
          children: [
            new TextRun({ text: `${letter}) `, bold: true }),
            ...parseChemicalText(st.text, {
              italics: isTrueMark,
              underline: isTrueMark ? {} : undefined,
              bold: false,
            })
          ],
          indent: { left: 450 },
          spacing: { before: 0, after: 0 }
        })
      );
    });
  });

  // PHẦN III
  children.push(new Paragraph({ text: "PHẦN III. Câu trắc nghiệm trả lời ngắn.", bold: true, spacing: sectionSpacing }));
  if (!isAnswerKey) {
    children.push(new Paragraph({ text: "Thí sinh trả lời từ câu 1 đến câu 6.", italic: true, spacing: { after: 150 } }));
  }

  data.part3.forEach((q, idx) => {
    children.push(new Paragraph({ 
      children: [new TextRun({ text: `Câu ${idx + 1}. `, bold: true }), ...parseChemicalText(q.question)], 
      spacing: isAnswerKey ? { before: 80 } : { before: 150, after: 80 } 
    }));

    if (isAnswerKey) {
      children.push(new Paragraph({ 
        children: [
          new TextRun({ text: "A. ", bold: true }),
          new TextRun({ text: `${q.answer}`, bold: true, italics: true, underline: {}, color: "0000FF" })
        ], 
        indent: { left: 450 },
        spacing: { before: 0, after: 0 }
      }));
    } else {
      children.push(new Paragraph({ text: "A. ...........................................................", indent: { left: 450 }, spacing: { before: 0, after: 0 } }));
    }
  });

  const doc = new Document({
    sections: [{
      properties: {
          page: { margin: { top: 720, bottom: 720, left: 720, right: 720 } }
      },
      children: children,
    }],
  });

  const blob = await Packer.toBlob(doc);
  saveAs(blob, `${isAnswerKey ? 'DapAn' : 'DeThi'}_${data.title.replace(/\s+/g, '_')}.docx`);
};

export interface MCQQuestion {
  question: string;
  options: string[]; 
  correctIndex: number;
}

export interface Statement {
  text: string;
  isTrue: boolean;
}

export interface TFScenario {
  context: string;
  statements: Statement[];
}

export interface ShortAnswerQuestion {
  question: string;
  answer: string | number;
}

export interface MatrixRow {
  topic: string;
  recognition: number;   // Nhận biết
  understanding: number; // Thông hiểu
  application: number;   // Vận dụng
  highApplication: number; // Vận dụng cao
}

export interface ExamData {
  title: string;
  grade: string;
  part1: MCQQuestion[];
  part2: TFScenario[];
  part3: ShortAnswerQuestion[];
  matrix: MatrixRow[];
}

export enum AppStatus {
  IDLE = 'IDLE',
  GENERATING = 'GENERATING',
  COMPLETED = 'COMPLETED',
  ERROR = 'ERROR'
}

export type GradeLevel = '10' | '11' | '12';

import { GoogleGenAI, Type } from "@google/genai";
import { ExamData, MatrixRow } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const generateExam = async (
  grade: string, 
  topic: string, 
  details: string, 
  existingMatrix?: MatrixRow[]
): Promise<ExamData> => {
  const modelName = 'gemini-3-pro-preview';

  const matrixInstruction = existingMatrix 
    ? `Sử dụng NGHIÊM NGẶT ma trận sau để soạn các câu hỏi (không được thay đổi số lượng câu ở mỗi mức độ): ${JSON.stringify(existingMatrix)}`
    : `Tạo một ma trận mới đảm bảo tỉ lệ nhận thức: Nhận biết 40%, Thông hiểu 30%, Vận dụng 30%.`;

  const systemInstruction = `
    Bạn là một chuyên gia soạn đề thi Hóa học THPT xuất sắc, am hiểu sâu sắc chương trình GDPT 2018.
    Nhiệm vụ: Tạo đề kiểm tra và ma trận cho KHỐI ${grade} - Chương: "${topic}".

    NGUỒN KIẾN THỨC TỔNG HỢP (BẮT BUỘC):
    1. Tổng hợp nội dung từ 3 bộ sách giáo khoa: Kết nối tri thức với cuộc sống, Cánh Diều, Chân trời sáng tạo.
    2. Tham khảo chuẩn kiến thức từ: Khan Academy, Chemistry LibreTexts, ACS, RSC, AP Chemistry, Chemistry World, ChemCollective.

    QUY TẮC PHÂN BỔ TỈ LỆ NHẬN THỨC (4:3:3):
    - Nhận biết: 40% (~11-12 lệnh hỏi).
    - Thông hiểu: 30% (~8-9 lệnh hỏi).
    - Vận dụng & Vận dụng cao: 30% (~8-9 lệnh hỏi).
    ${matrixInstruction}

    CẤU TRÚC ĐỀ (Tổng 28 câu):
    1. Phần 1: 18 câu MCQ. Phương án trong 'options' KHÔNG kèm nhãn A.B.C.D.
    2. Phần 2: 4 bối cảnh Đúng/Sai (mỗi bối cảnh 4 ý).
    3. Phần 3: 6 câu trả lời ngắn (BÀI TOÁN ĐỊNH LƯỢNG THỰC TẾ).

    QUY TẮC NỘI DUNG:
    - Danh pháp: Tiếng Anh IUPAC (ví dụ: Aluminum, Sulfuric acid...).
    - Công thức: Viết dạng text (H2SO4, Fe2+...).
    - Ngôn ngữ: Tiếng Việt.
  `;

  const response = await ai.models.generateContent({
    model: modelName,
    contents: `Soạn đề ôn tập Hóa ${grade} - Chương: ${topic}. Yêu cầu: ${details}. Đảm bảo tỉ lệ 4:3:3 và tích hợp 3 bộ sách + nguồn quốc tế.`,
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          grade: { type: Type.STRING },
          part1: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                question: { type: Type.STRING },
                options: { type: Type.ARRAY, items: { type: Type.STRING } },
                correctIndex: { type: Type.INTEGER }
              },
              required: ["question", "options", "correctIndex"]
            }
          },
          part2: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                context: { type: Type.STRING },
                statements: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      text: { type: Type.STRING },
                      isTrue: { type: Type.BOOLEAN }
                    },
                    required: ["text", "isTrue"]
                  }
                }
              },
              required: ["context", "statements"]
            }
          },
          part3: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                question: { type: Type.STRING },
                answer: { type: Type.STRING }
              },
              required: ["question", "answer"]
            }
          },
          matrix: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                topic: { type: Type.STRING },
                recognition: { type: Type.INTEGER },
                understanding: { type: Type.INTEGER },
                application: { type: Type.INTEGER },
                highApplication: { type: Type.INTEGER }
              },
              required: ["topic", "recognition", "understanding", "application", "highApplication"]
            }
          }
        },
        required: ["title", "grade", "part1", "part2", "part3", "matrix"]
      }
    }
  });

  const text = response.text;
  if (!text) throw new Error("Không nhận được phản hồi từ AI");
  return JSON.parse(text) as ExamData;
};

import React from 'react';
import { ExamData } from '../types';

interface ExamRendererProps {
  data: ExamData;
  showAnswers?: boolean;
}

const ExamRenderer: React.FC<ExamRendererProps> = ({ data, showAnswers = false }) => {
  const formatFormula = (text: string) => {
    if (!text) return null;
    const regex = /((?<=[a-zA-Z\d\)])\d*[\+\-]|(?<=[a-zA-Z\)])\d+)/g;
    const parts = text.split(regex);

    return parts.map((part, i) => {
      if (!part) return null;
      if (/^\d*[\+\-]$/.test(part)) {
        return <sup key={i} className="text-[0.75em] leading-[0] inline-block align-baseline translate-y-[-0.3em] font-medium">{part}</sup>;
      }
      if (/^\d+$/.test(part)) {
        return <sub key={i} className="text-[0.75em] leading-[0] inline-block align-baseline translate-y-[0.1em] font-medium">{part}</sub>;
      }
      return <span key={i}>{part}</span>;
    });
  };

  const getLabel = (index: number) => {
    return ["A", "B", "C", "D"][index] + ". ";
  };

  return (
    <div id="exam-preview" className={`bg-white p-6 md:p-10 shadow-xl rounded-lg border border-slate-200 max-w-4xl mx-auto text-slate-800 leading-normal overflow-hidden ${showAnswers ? 'bg-blue-50/30' : ''}`}>
      <h1 className="text-xl font-bold text-center mb-6 uppercase text-slate-900 border-b pb-3">
        {data.title} {showAnswers && <span className="text-blue-600 block text-sm mt-1">(BẢN ĐÁP ÁN)</span>}
      </h1>

      {/* Part 1 */}
      <section className="mb-8">
        <h2 className="font-bold text-md mb-2 underline decoration-indigo-300">PHẦN I. Câu trắc nghiệm nhiều phương án lựa chọn.</h2>
        <div className="space-y-4">
          {data.part1.map((q, idx) => (
            <div key={idx} className="text-sm">
              <p className="font-medium mb-1">
                <span className="font-bold">Câu {idx + 1}.</span> {formatFormula(q.question)}
              </p>
              <div className="mt-1 flex flex-col gap-1">
                {q.options.map((opt, oIdx) => {
                  const isCorrect = showAnswers && oIdx === q.correctIndex;
                  const label = getLabel(oIdx);
                  const cleanOpt = opt.replace(/^[A-D]\.\s*/, '');

                  return (
                    <div key={oIdx} className={`pl-5 py-0.5 transition-colors ${isCorrect ? 'italic underline text-blue-700 font-medium' : ''}`}>
                      <span className="font-bold mr-1">{label}</span>
                      {formatFormula(cleanOpt)}
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* Part 2 */}
      <section className="mb-8">
        <h2 className="font-bold text-md mb-2 underline decoration-indigo-300">PHẦN II. Câu trắc nghiệm đúng sai.</h2>
        <div className="space-y-6">
          {data.part2.map((sc, idx) => (
            <div key={idx} className="text-sm">
              <div className="font-medium mb-2">
                <span className="font-bold">Câu {idx + 1}.</span> {formatFormula(sc.context)}
              </div>
              <div className="space-y-1">
                {sc.statements.map((st, sIdx) => {
                  const letter = ["a", "b", "c", "d"][sIdx];
                  const isTrueMark = showAnswers && st.isTrue;
                  return (
                    <div key={sIdx} className="flex gap-2 pl-5 py-0.5 items-baseline">
                      <span className="font-bold whitespace-nowrap">{letter})</span>
                      <p className={`${isTrueMark ? 'italic underline text-blue-700' : ''}`}>
                        {formatFormula(st.text)}
                        {showAnswers && <span className={`text-[10px] ml-2 font-bold ${st.isTrue ? 'text-blue-500' : 'text-slate-400'}`}>({st.isTrue ? 'Đ' : 'S'})</span>}
                      </p>
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* Part 3 */}
      <section>
        <h2 className="font-bold text-md mb-2 underline decoration-indigo-300">PHẦN III. Câu trắc nghiệm trả lời ngắn.</h2>
        <div className="space-y-5">
          {data.part3.map((q, idx) => (
            <div key={idx} className="text-sm">
              <div className="font-medium">
                <span className="font-bold">Câu {idx + 1}.</span> {formatFormula(q.question)}
              </div>
              <div className="mt-2 pl-5">
                {showAnswers ? (
                  <div className="font-bold text-blue-700 italic border-l-4 border-blue-400 pl-3 py-1 bg-blue-50/50 rounded-r">
                    <span className="underline">Đáp án: {q.answer}</span>
                  </div>
                ) : (
                  <div className="flex items-center gap-2 py-1">
                    <span className="font-bold">Đáp án:</span>
                    <div className="w-full max-w-[150px] border-b-2 border-dotted border-slate-300 h-5"></div>
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
};

export default ExamRenderer;

