                    ) : (
                      <>
                        <ImageIcon className="w-8 h-8 text-slate-300 mb-2" />
                        <p className="text-xs text-slate-400 font-medium text-center">Nhấp để tải lên ảnh ma trận đã tạo trước đó</p>
                      </>
                    )}
                    <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-3 pt-4 border-t border-slate-50">
                <button onClick={() => handleGenerate('new')} disabled={!topic} className="py-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-black text-sm shadow-lg disabled:bg-slate-200 transition-all flex items-center justify-center gap-2 uppercase tracking-widest"><RefreshCw className="w-4 h-4"/> Đề & Ma trận mới</button>
                <button onClick={() => handleGenerate('reuse')} disabled={!topic || !savedMatrices[topic]} className="py-4 bg-emerald-600 hover:bg-emerald-700 text-white rounded-2xl font-black text-sm shadow-lg disabled:bg-slate-100 disabled:text-slate-300 transition-all flex items-center justify-center gap-2 uppercase tracking-widest"><PlusCircle className="w-4 h-4"/> Sử dụng ma trận cũ</button>
                <button onClick={() => handleGenerate('image')} disabled={!topic || !matrixImage} className="py-4 bg-slate-800 hover:bg-black text-white rounded-2xl font-black text-sm shadow-lg disabled:bg-slate-100 disabled:text-slate-300 transition-all flex items-center justify-center gap-2 uppercase tracking-widest"><ImageIcon className="w-4 h-4"/> Dùng ma trận từ ảnh</button>
              </div>
            </div>
